<?php
session_start();
require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb12d($ep){
  $ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));
  curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPGET=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY],CURLOPT_TIMEOUT=>25]);
  $b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];
}
$sources=sb12d('discovery_intelligence_sources?select=*&order=priority_score.desc,created_at.desc&limit=300');
$opps=sb12d('discovery_opportunity_queue?select=*&order=priority_score.desc,created_at.desc&limit=300');
$cron=sb12d('cron_schedule_registry?select=*&order=recommended_time.asc&limit=100');
$stats=['sources'=>count($sources),'opps'=>count($opps),'sellers'=>0,'buyers'=>0,'builders'=>0,'relocation'=>0,'developers'=>0];
foreach($opps as $o){$t=$o['opportunity_type']??'';if(isset($stats[$t]))$stats[$t]++;}
$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';
