<p><a class="btn" target="_blank" href="/lead-engine/build-discovery-intelligence.php?key=<?=h($cronKey)?>">Build V12 Discovery</a><a class="btn light" href="/dashboard/overnight-lead-research.php">Overnight Research</a></p>
<section class="grid"><div class="kpi"><div class="n"><?=h($stats['sources'])?></div>Sources</div><div class="kpi"><div class="n"><?=h($stats['opps'])?></div>Opportunities</div><div class="kpi"><div class="n"><?=h($stats['sellers'])?></div>Sellers</div><div class="kpi"><div class="n"><?=h($stats['buyers'])?></div>Buyers</div><div class="kpi"><div class="n"><?=h($stats['relocation'])?></div>Relocation</div><div class="kpi"><div class="n"><?=h($stats['builders']+$stats['developers'])?></div>Builder/Dev</div></section>
<div class="layout"><section class="panel"><h2>Discovery Opportunity Queue</h2><table><tr><th>Score</th><th>Market</th><th>Offer</th><th>Ad Angle</th><th>Compliance</th></tr><?php foreach($opps as $o):?><tr><td><strong><?=h($o['priority_score'])?></strong><div class="muted"><?=h($o['opportunity_type'])?></div></td><td><?=h($o['market'])?><div class="muted"><?=h($o['town'])?><br><?=h($o['audience'])?></div></td><td><strong><?=h($o['offer'])?></strong><div class="muted"><?=h($o['landing_page'])?></div></td><td><?=h($o['ad_angle'])?></td><td><?=h($o['compliance_status'])?><div class="muted"><?=h($o['notes'])?></div></td></tr><?php endforeach;?></table></section>
<section class="panel"><h2>Cron Schedule</h2><table><tr><th>Job</th><th>Time</th><th>URL</th></tr><?php foreach($cron as $c):?><tr><td><strong><?=h($c['job_name'])?></strong><div class="muted"><?=h($c['notes'])?></div></td><td><?=h($c['recommended_time'])?></td><td><small><?=h($c['job_url'])?></small></td></tr><?php endforeach;?></table></section></div>
